// The built-in access data format, version 1 (ADR 0024): one JSON file per
// dataset in src/access/data/, generated by scripts/prepare-access-data.mts.
import type { AccessRecord, AccessSource, LockMarker } from "@/core/access";
import type { CalendarDate } from "@/core/calendarDate";
import type { Obstacle } from "@/core/obstacle";
import type { OfficialAire, OfficialStretch } from "@/core/officialAire";

export const ACCESS_DATA_FORMAT = "packraft-go/access-data";

export type AccessDataset = {
  readonly format: typeof ACCESS_DATA_FORMAT;
  readonly version: 1;
  /** e.g. "regions", "flanders". */
  readonly id: string;
  readonly title: string;
  /** Credit for the geometry, shown with the data. */
  readonly attribution: string;
  /** When the geometry was extracted from OpenStreetMap, YYYY-MM-DD. */
  readonly extracted: string;
  readonly records: readonly AccessRecord[];
};

export const LOCK_DATA_FORMAT = "packraft-go/lock-data";

/** The lock markers of Flanders and Brussels, prepared offline from OpenStreetMap. */
export type LockDataset = {
  readonly format: typeof LOCK_DATA_FORMAT;
  readonly version: 1;
  readonly id: "locks";
  readonly title: string;
  readonly attribution: string;
  readonly extracted: string;
  readonly locks: readonly LockMarker[];
};

export const OSM_ATTRIBUTION = "Geometry © OpenStreetMap contributors, ODbL";

/** The credit for the SPW's data (ADR 0035). */
export const SPW_ATTRIBUTION = "Sources des données : Service public de Wallonie";

export const OFFICIAL_AIRE_DATA_FORMAT = "packraft-go/official-aire-data";

/** An official aire as stored: the source and date are the snapshot's, so a refresh changes one line. */
export type StoredOfficialAire = Omit<OfficialAire, "id" | "source" | "snapshot">;

/** The official aires (ADR 0035), prepared offline from the SPW's PKAYAK layer 3. */
export type OfficialAireDataset = {
  readonly format: typeof OFFICIAL_AIRE_DATA_FORMAT;
  readonly version: 1;
  readonly id: "official-aires";
  readonly title: string;
  readonly attribution: string;
  readonly source: AccessSource;
  /** When the snapshot was taken, YYYY-MM-DD. */
  readonly snapshot: CalendarDate;
  readonly aires: readonly StoredOfficialAire[];
};

export const OBSTACLE_DATA_FORMAT = "packraft-go/obstacle-data";

/** An obstacle as stored: the source and date are the snapshot's, so a refresh changes one line. */
export type StoredObstacle = Omit<Obstacle, "id" | "source" | "snapshot">;

/** The obstacles (ADR 0035), prepared offline from the SPW's PKAYAK layer 1. */
export type ObstacleDataset = {
  readonly format: typeof OBSTACLE_DATA_FORMAT;
  readonly version: 1;
  readonly id: "obstacles";
  readonly title: string;
  readonly attribution: string;
  readonly source: AccessSource;
  /** When the snapshot was taken, YYYY-MM-DD. */
  readonly snapshot: CalendarDate;
  readonly obstacles: readonly StoredObstacle[];
};

export const OFFICIAL_STRETCH_DATA_FORMAT = "packraft-go/official-stretch-data";

/** Each official stretch's id and name (ADR 0035), prepared offline from the SPW's PKAYAK layer 5. */
export type OfficialStretchDataset = {
  readonly format: typeof OFFICIAL_STRETCH_DATA_FORMAT;
  readonly version: 1;
  readonly id: "official-stretches";
  readonly title: string;
  readonly attribution: string;
  readonly source: AccessSource;
  /** When the snapshot was taken, YYYY-MM-DD. */
  readonly snapshot: CalendarDate;
  readonly stretches: readonly OfficialStretch[];
};
